mapper.update:
UPDATE INTSTKP
   SET LOCAKY = #{LOCAKY}
     , QTYPHY = #{QTYRCV}
     , PHYCHK = 'V'
     , LMODAT = TO_CHAR(SYSDATE, 'YYYYMMDD')
     , LMOTIM = TO_CHAR(SYSDATE, 'HH24MISS')
     , LMOUSR = #{SES_USER_ID}
     , PHYDAT = TO_CHAR(SYSDATE, 'YYYYMMDD')
     , PHYTIM = TO_CHAR(SYSDATE, 'HH24MISS')
     , PHYUSR = #{SES_USER_ID}
 WHERE LOTA14 = #{LOTA14}

mapper.select:
WITH WAREKY_T AS ( SELECT IH.INTSEQ , MIN(T2.WAREKY) AS WAREKY FROM INTSTKH IH INNER JOIN INTSTKI T2 ON T2.INTSEQ = IH.INTSEQ AND T2.STKSEQ = ( SELECT MIN(X.STKSEQ) FROM INTSTKI X WHERE X.INTSEQ = T2.INTSEQ AND X.WAREKY != ' ' AND ROWNUM =1 ) WHERE EXISTS ( SELECT 1 FROM INTSTKI II WHERE II.INTSEQ = IH.INTSEQ
${RANGE_SQL}
) GROUP BY IH.INTSEQ
) SELECT IH.INTSEQ , IH.INTDAT , IH.CREDAT , IH.CRETIM , IH.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.CREUSR),' ') AS CUSRNM , IH.LMODAT , IH.LMOTIM , IH.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.LMOUSR),' ') AS LUSRNM , IH.SKUGBN
, WT.WAREKY FROM INTSTKH IH LEFT OUTER JOIN WAREKY_T WT ON WT.INTSEQ = IH.INTSEQ WHERE EXISTS ( SELECT 'X' FROM INTSTKI II WHERE II.INTSEQ = IH.INTSEQ
${RANGE_SQL}
) ORDER BY IH.INTSEQ DESC

WITH WAREKY_T AS ( SELECT II.INTSEQ , MIN(II.WAREKY) AS WAREKY FROM INTSTKI II INNER JOIN INTSTKH IH ON IH.INTSEQ = II.INTSEQ
WHERE 1=1
${RANGE_SQL}
GROUP BY II.INTSEQ ) SELECT IH.INTSEQ , IH.INTDAT , IH.CREDAT , IH.CRETIM , IH.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.CREUSR),' ') AS CUSRNM , IH.LMODAT , IH.LMOTIM , IH.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.LMOUSR),' ') AS LUSRNM , IH.SKUGBN , ( SELECT X.WAREKY FROM WAREKY_T X WHERE X.INTSEQ = IH.INTSEQ ) AS WAREKY FROM INTSTKH IH WHERE 1=1
AND EXISTS ( SELECT 'X' FROM INTSTKI II WHERE II.INTSEQ = IH.INTSEQ
${RANGE_SQL}
) ORDER BY IH.INTSEQ DESC

WITH LOTA02_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA02' ), LOTA06_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA06' ), LOTA08_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'NATNKY' ), SLM_T AS ( SELECT SLM.OWNRKY , SLM.PLNTKY , SLM.STLKY , SLM.STLNM FROM STLMA SLM WHERE SLM.OWNRKY = #{OWNRKY} ), UIM_T AS ( SELECT UM.OWNRKY , UM.PLNTKY , UM.UNITNO , UM.UNITNM FROM UNITMA UM WHERE UM.OWNRKY = #{OWNRKY} ) SELECT IH.INTSEQ , IH.INTDAT , II.STKSEQ , II.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = II.WAREKY),' ') AS WARENM , II.SKUKEY , SM.DESC01 , II.QTYRCV , II.UOMKEY , II.PALQTY , II.LOTA02 , ( SELECT X.CDESC1 FROM LOTA02_T X WHERE X.CMCDVL=II.LOTA02 ) AS LOTA02NM , II.LOTA01 , ( SELECT X.STLNM FROM SLM_T X WHERE X.PLNTKY = II.LOTA02 AND X.STLKY = II.LOTA01 ) AS LOTA01NM , II.LOTA04 , ( SELECT X.UNITNM FROM UIM_T X WHERE X.PLNTKY = II.LOTA02 AND X.UNITNO = II.LOTA04 ) AS LOTA04NM , II.LOTA06 , ( SELECT X.CDESC1 FROM LOTA06_T X WHERE X.CMCDVL=II.LOTA06 ) AS LOTA06NM , II.LOTA08 , ( SELECT X.CDESC1 FROM LOTA08_T X WHERE X.CMCDVL=II.LOTA08 ) AS LOTA08NM , II.LOTA07 , II.LOTA09 , LT09.NAME01 AS LOTA09NM , II.LOTA10 , II.LOTA11 , II.LOTA12 , II.LOTA13 , II.LOTA14 , II.LOTA15 , II.LOTA16 , II.LOTA17 , II.LOTA03 , II.LOTA21 , II.LOTA23 , II.LOTA24 , II.LOTA41 , II.LOTA42 , LT42.NAME01 AS LOTA42NM , II.CHKFLG , II.REMARK , II.CREDAT , II.CRETIM , II.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = II.CREUSR),' ') AS CUSRNM , II.LMODAT , II.LMOTIM , II.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = II.LMOUSR),' ') AS LUSRNM FROM INTSTKH IH INNER JOIN INTSTKI II ON II.INTSEQ = IH.INTSEQ LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY=#{OWNRKY} AND SM.SKUKEY = II.SKUKEY LEFT OUTER JOIN BZPTN LT09 ON LT09.PTNRKY = II.LOTA09 AND LT09.PTNRTY = 'CT' AND LT09.OWNRKY = #{OWNRKY} LEFT OUTER JOIN BZPTN LT42 ON LT42.PTNRKY = II.LOTA42 AND LT42.PTNRTY = 'VD' AND LT42.OWNRKY = #{OWNRKY} WHERE IH.INTSEQ = #{INTSEQ}
${RANGE_SQL}
ORDER BY IH.INTSEQ, II.STKSEQ

WITH LOTA02_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA02' ), LOTA06_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA06' ), LOTA08_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'NATNKY' ), SLM_T AS ( SELECT SLM.OWNRKY , SLM.PLNTKY , SLM.STLKY , SLM.STLNM FROM STLMA SLM WHERE SLM.OWNRKY = #{OWNRKY} ), UIM_T AS ( SELECT UM.OWNRKY , UM.PLNTKY , UM.UNITNO , UM.UNITNM FROM UNITMA UM WHERE UM.OWNRKY = #{OWNRKY} ) SELECT IH.INTSEQ , IH.INTDAT , IP.STKSEQ , IP.PALSEQ , IP.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = IP.WAREKY),' ') AS WARENM , IP.SKUKEY , SM.DESC01 , IP.QTYRCV , IP.UOMKEY , IP.LOTA02 , ( SELECT X.CDESC1 FROM LOTA02_T X WHERE X.CMCDVL=IP.LOTA02 ) AS LOTA02NM , IP.LOTA01 , ( SELECT X.STLNM FROM SLM_T X WHERE X.PLNTKY = IP.LOTA02 AND X.STLKY = IP.LOTA01 ) AS LOTA01NM , IP.LOTA04 , ( SELECT X.UNITNM FROM UIM_T X WHERE X.PLNTKY = IP.LOTA02 AND X.UNITNO = IP.LOTA04 ) AS LOTA04NM , IP.LOTA06 , ( SELECT X.CDESC1 FROM LOTA06_T X WHERE X.CMCDVL=IP.LOTA06 ) AS LOTA06NM , IP.LOTA08 , ( SELECT X.CDESC1 FROM LOTA08_T X WHERE X.CMCDVL=IP.LOTA08 ) AS LOTA08NM , IP.LOTA07 , IP.LOTA09 , LT09.NAME01 AS LOTA09NM , IP.LOTA10 , IP.LOTA11 , IP.LOTA12 , IP.LOTA13 , IP.LOTA14 , IP.LOTA15 , IP.LOTA16 , IP.LOTA17 , IP.LOTA03 , IP.LOTA21 , IP.LOTA23 , IP.LOTA24 , IP.LOTA41 , IP.LOTA42 , LT42.NAME01 AS LOTA42NM , IP.QTYPHY , IP.PHYCHK , IP.INTCHK , IP.CREDAT , IP.CRETIM , IP.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IP.CREUSR),' ') AS CUSRNM , IP.LMODAT , IP.LMOTIM , IP.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IP.LMOUSR),' ') AS LUSRNM , IP.RECVKY , IP.RECVIT , IP.DOCTXT , IP.DOCDAT , LM.AREAKY , LM.ZONEKY , IP.LOCAKY , II.PALQTY FROM INTSTKH IH INNER JOIN INTSTKI II ON II.INTSEQ = IH.INTSEQ INNER JOIN INTSTKP IP ON IP.INTSEQ = II.INTSEQ AND IP.STKSEQ = II.STKSEQ LEFT OUTER JOIN SKUMA SM ON SM.SKUKEY = IP.SKUKEY LEFT OUTER JOIN BZPTN LT09 ON LT09.PTNRKY = IP.LOTA09 AND LT09.PTNRTY = 'CT' AND LT09.OWNRKY = #{OWNRKY} LEFT OUTER JOIN BZPTN LT42 ON LT42.PTNRKY = IP.LOTA42 AND LT42.PTNRTY = 'VD' AND LT42.OWNRKY = #{OWNRKY} LEFT OUTER JOIN DOCTM DT ON DT.DOCUTY = '199' LEFT OUTER JOIN LOCMA LM ON LM.WAREKY = IP.WAREKY AND LM.LOCAKY = DT.SYSLOC WHERE IH.INTSEQ = #{INTSEQ}
${RANGE_SQL}
ORDER BY IH.INTSEQ DESC, IP.STKSEQ, IP.PALSEQ

SELECT A.WAREKY , A.LOTA02 , A.INTCHK , ( CASE WHEN A.INTCHK = 'Y' THEN A.DOCDAT ELSE TO_CHAR(SYSDATE,'YYYYMMDD') END ) AS DOCDAT , A.DOCDAT AS DOCDAT_ORG , ( CASE WHEN A.INTCHK = 'Y' THEN A.DOCTXT ELSE '기초재고셋업' END ) AS DOCTXT , A.CNT , A.QTYPHY , A.SKUG05 FROM ( SELECT IP.WAREKY , IP.LOTA02 , DECODE(IP.INTCHK, 'V', 'Y', 'N') AS INTCHK , IP.DOCDAT , IP.DOCTXT , COUNT(1) AS CNT , SUM(IP.QTYPHY) AS QTYPHY , SM.SKUG05 FROM INTSTKP IP INNER JOIN INTSTKH IH ON IH.INTSEQ = IP.INTSEQ LEFT OUTER JOIN SKUMA SM ON SM.SKUKEY = IP.SKUKEY WHERE IP.PHYCHK = 'V' AND IP.QTYPHY > 0 GROUP BY IP.WAREKY, IP.LOTA02, IP.INTCHK, SM.SKUG05, IP.DOCDAT, IP.DOCTXT ORDER BY IP.WAREKY, IP.LOTA02, IP.INTCHK DESC, SM.SKUG05, IP.DOCDAT, IP.DOCTXT ) A WHERE 1=1
AND A.INTCHK = #{INTCHK}
${RANGE_SQL}

mapper.update:
		UPDATE INTSTKP IP SET INTCHK = 'A'
        WHERE IP.PHYCHK = 'V'
          AND IP.WAREKY = #{WAREKY}
          AND IP.LOTA02 = #{LOTA02}
          AND TRIM(IP.INTCHK) IS NULL
          AND EXISTS (
                       SELECT 1 
                       FROM SKUMA SM
                       WHERE SM.SKUKEY=IP.SKUKEY
                         AND SM.SKUG05 = #{SKUG05}
                     )

		UPDATE INTSTKP IP SET INTCHK = ' '
        WHERE IP.PHYCHK = 'V'
          AND IP.WAREKY = #{WAREKY}
          AND IP.LOTA02 = #{LOTA02}
          AND IP.INTCHK = 'A'
          AND EXISTS (
                       SELECT 1 
                       FROM SKUMA SM
                       WHERE SM.SKUKEY=IP.SKUKEY
                         AND SM.SKUG05 = #{SKUG05}
                     )

mapper.select:
SELECT IH.INTSEQ , IH.INTDAT , IH.CREDAT , IH.CRETIM , IH.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.CREUSR),' ') AS CUSRNM , IH.LMODAT , IH.LMOTIM , IH.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IH.LMOUSR),' ') AS LUSRNM , IH.SKUGBN FROM INTSTKH IH WHERE IH.SKUGBN = '10' AND EXISTS ( SELECT 'X' FROM INTSTKI II WHERE II.INTSEQ = IH.INTSEQ
${RANGE_SQL}
) ORDER BY IH.INTSEQ DESC

WITH LOTA02_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA02' ), LOTA06_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA06' ), LOTA08_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'NATNKY' ), SLM_T AS ( SELECT SLM.OWNRKY , SLM.PLNTKY , SLM.STLKY , SLM.STLNM FROM STLMA SLM WHERE SLM.OWNRKY = #{OWNRKY} ), UIM_T AS ( SELECT UM.OWNRKY , UM.PLNTKY , UM.UNITNO , UM.UNITNM FROM UNITMA UM WHERE UM.OWNRKY = #{OWNRKY} ) SELECT IH.INTSEQ , IH.INTDAT , II.STKSEQ , II.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = II.WAREKY),' ') AS WARENM , II.SKUKEY , SM.DESC01 , II.QTYRCV , II.UOMKEY , II.PALQTY , II.LOTA02 , ( SELECT X.CDESC1 FROM LOTA02_T X WHERE X.CMCDVL=II.LOTA02 ) AS LOTA02NM , II.LOTA01 , ( SELECT X.STLNM FROM SLM_T X WHERE X.PLNTKY = II.LOTA02 AND X.STLKY = II.LOTA01 ) AS LOTA01NM , II.LOTA04 , ( SELECT X.UNITNM FROM UIM_T X WHERE X.PLNTKY = II.LOTA02 AND X.UNITNO = II.LOTA04 ) AS LOTA04NM , II.LOTA06 , ( SELECT X.CDESC1 FROM LOTA06_T X WHERE X.CMCDVL=II.LOTA06 ) AS LOTA06NM , II.LOTA08 , ( SELECT X.CDESC1 FROM LOTA08_T X WHERE X.CMCDVL=II.LOTA08 ) AS LOTA08NM , II.LOTA07 , II.LOTA09 , LT09.NAME01 AS LOTA09NM , II.LOTA10 , II.LOTA11 , II.LOTA12 , II.LOTA13 , II.LOTA14 , II.LOTA15 , II.LOTA16 , II.LOTA17 , II.LOTA03 , II.LOTA21 , II.LOTA23 , II.LOTA24 , II.LOTA41 , II.LOTA42 , LT42.NAME01 AS LOTA42NM , II.CHKFLG , II.REMARK , II.CREDAT , II.CRETIM , II.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = II.CREUSR),' ') AS CUSRNM , II.LMODAT , II.LMOTIM , II.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = II.LMOUSR),' ') AS LUSRNM , IH.SKUGBN FROM INTSTKH IH INNER JOIN INTSTKI II ON II.INTSEQ = IH.INTSEQ LEFT OUTER JOIN SKUMA SM ON SM.SKUKEY = II.SKUKEY LEFT OUTER JOIN BZPTN LT09 ON LT09.PTNRKY = II.LOTA09 AND LT09.PTNRTY = 'CT' AND LT09.OWNRKY = #{OWNRKY} LEFT OUTER JOIN BZPTN LT42 ON LT42.PTNRKY = II.LOTA42 AND LT42.PTNRTY = 'VD' AND LT42.OWNRKY = #{OWNRKY} WHERE IH.INTSEQ = #{INTSEQ}
${RANGE_SQL}
ORDER BY IH.INTSEQ DESC, II.STKSEQ

WITH LOTA02_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA02' ), LOTA06_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'LOTA06' ), LOTA08_T AS ( SELECT CD.CMCDVL , NVL(CL.CDESC1, CD.CDESC1) AS CDESC1 FROM CMCDV CD LEFT OUTER JOIN CMCDV_LANG CL ON CL.LANGKY = #{LANGKY} AND CL.CMCDKY = CD.CMCDKY AND CL.CMCDVL = CD.CMCDVL WHERE CD.CMCDKY = 'NATNKY' ), SLM_T AS ( SELECT SLM.OWNRKY , SLM.PLNTKY , SLM.STLKY , SLM.STLNM FROM STLMA SLM WHERE SLM.OWNRKY = #{OWNRKY} ), UIM_T AS ( SELECT UM.OWNRKY , UM.PLNTKY , UM.UNITNO , UM.UNITNM FROM UNITMA UM WHERE UM.OWNRKY = #{OWNRKY} ) SELECT IH.INTSEQ , IH.INTDAT , IP.STKSEQ , IP.PALSEQ , IP.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = IP.WAREKY),' ') AS WARENM , IP.SKUKEY , SM.DESC01 , IP.QTYRCV , IP.UOMKEY , IP.LOTA02 , ( SELECT X.CDESC1 FROM LOTA02_T X WHERE X.CMCDVL=IP.LOTA02 ) AS LOTA02NM , IP.LOTA01 , ( SELECT X.STLNM FROM SLM_T X WHERE X.PLNTKY = IP.LOTA02 AND X.STLKY = IP.LOTA01 ) AS LOTA01NM , IP.LOTA04 , ( SELECT X.UNITNM FROM UIM_T X WHERE X.PLNTKY = IP.LOTA02 AND X.UNITNO = IP.LOTA04 ) AS LOTA04NM , IP.LOTA06 , ( SELECT X.CDESC1 FROM LOTA06_T X WHERE X.CMCDVL=IP.LOTA06 ) AS LOTA06NM , IP.LOTA08 , ( SELECT X.CDESC1 FROM LOTA08_T X WHERE X.CMCDVL=IP.LOTA08 ) AS LOTA08NM , IP.LOTA07 , IP.LOTA09 , LT09.NAME01 AS LOTA09NM , IP.LOTA10 , IP.LOTA11 , IP.LOTA12 , IP.LOTA13 , IP.LOTA14 , IP.LOTA15 , IP.LOTA16 , IP.LOTA17 , IP.LOTA03 , IP.LOTA21 , IP.LOTA23 , IP.LOTA24 , IP.LOTA41 , IP.LOTA42 , LT42.NAME01 AS LOTA42NM , IP.QTYPHY , IP.PHYCHK , IP.INTCHK , IP.CREDAT , IP.CRETIM , IP.CREUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IP.CREUSR),' ') AS CUSRNM , IP.LMODAT , IP.LMOTIM , IP.LMOUSR , NVL((SELECT NMLAST FROM USRMA WHERE USERID = IP.LMOUSR),' ') AS LUSRNM , IP.RECVKY , IP.RECVIT , IP.DOCTXT , IP.DOCDAT , LM.AREAKY , LM.ZONEKY , IP.LOCAKY , II.PALQTY , IH.SKUGBN , IP.TMP_LOTA14 FROM INTSTKH IH INNER JOIN INTSTKI II ON II.INTSEQ = IH.INTSEQ INNER JOIN INTSTKP IP ON IP.INTSEQ = II.INTSEQ AND IP.STKSEQ = II.STKSEQ LEFT OUTER JOIN SKUMA SM ON SM.SKUKEY = IP.SKUKEY LEFT OUTER JOIN BZPTN LT09 ON LT09.PTNRKY = IP.LOTA09 AND LT09.PTNRTY = 'CT' AND LT09.OWNRKY = #{OWNRKY} LEFT OUTER JOIN BZPTN LT42 ON LT42.PTNRKY = IP.LOTA42 AND LT42.PTNRTY = 'VD' AND LT42.OWNRKY = #{OWNRKY} LEFT OUTER JOIN DOCTM DT ON DT.DOCUTY = '199' LEFT OUTER JOIN LOCMA LM ON LM.WAREKY = IP.WAREKY AND LM.LOCAKY = DT.SYSLOC WHERE IH.INTSEQ = #{INTSEQ}
${RANGE_SQL}
ORDER BY IH.INTSEQ DESC, IP.STKSEQ, IP.PALSEQ
